    \@Test
    void cancellingTellsStaffOnlyWhatConcernsThem() {
        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
        service.cancel(pending.id());
        assertEquals(0, sentMessages.all().size());

        Reservation paid = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));
        Reservation lost = service.create(stay(202, "2027-03-10", "2027-03-12", 2, RatePlan.NON_REFUNDABLE));
        service.confirm(paid.id());
        service.confirm(lost.id());
        int before = sentMessages.all().size();

        service.cancel(paid.id());
        List<Message> afterPaid = sentMessages.all().subList(before, sentMessages.all().size());
        assertEquals(2, afterPaid.size());
        assertEquals("Reserva cancelada - quarto 201", afterPaid.get(0).subject());
        assertEquals("Reembolso - reserva " + paid.id(), afterPaid.get(1).subject());
        assertTrue(afterPaid.get(1).body().contains("R\$ "));

        int mid = sentMessages.all().size();
        service.cancel(lost.id());
        List<Message> afterLost = sentMessages.all().subList(mid, sentMessages.all().size());
        assertEquals(1, afterLost.size());
        assertEquals("Reserva cancelada - quarto 202", afterLost.get(0).subject());
    }

